typedef float rational_t;

struct vector3d {
    float x;
    float y;
    float z;

    vector3d operator-(const vector3d& other) const {
        vector3d result = {x - other.x, y - other.y, z - other.z};
        return result;
    }

    float length2() const {
        return x * x + y * y + z * z;
    }
};

struct po {
    char padding[48];
    vector3d position;
};

struct entity {
    char padding[80];
    po* my_abs_po;

    const vector3d& get_abs_position() const {
        return my_abs_po->position;
    }
};

class ai_locomotion {
    char padding_to_start_pos[0x94];
    vector3d start_pos;
    vector3d last_pos;
    vector3d target_pos;
    rational_t tgtrange;
    bool running_speed;
    bool use_path;
    char padding_to_path_tries[2];
    int path_tries;
    bool wait_until_reached;
    bool wait_for_facing;
    bool in_service;
    char padding_to_type;
    int type;
    bool facing;
    bool playing_face_anim;
    char padding_to_face_dir[2];
    vector3d face_dir;
    rational_t turn_speed;
    rational_t jockey_timer;
    rational_t jockey_stuck_timer;
    vector3d last_jockey_pos;
    vector3d jockey_pos;
    vector3d jockey_dir;
    rational_t jockey_speed;
    bool jockey;

public:
    entity* get_my_entity() const
        __asm__("get_my_entity__C13ai_locomotion");
    void stop_jockey()
        __asm__("stop_jockey__13ai_locomotion");
    void going_into_service()
        __asm__("going_into_service__13ai_locomotion");
    void going_out_of_service()
        __asm__("going_out_of_service__13ai_locomotion");
    bool set_destination(
        const vector3d& pos,
        rational_t radius,
        bool fast,
        bool path_find,
        bool force_finish)
        __asm__("set_destination__13ai_locomotionRC8vector3dfbN23");
};

__asm__(".equ get_my_entity__C13ai_locomotion,0x00106EA0");
__asm__(".equ stop_jockey__13ai_locomotion,0x00108418");
__asm__(".equ going_into_service__13ai_locomotion,0x00109268");
__asm__(".equ going_out_of_service__13ai_locomotion,0x00109278");

bool ai_locomotion::set_destination(
    const vector3d& pos,
    rational_t radius,
    bool fast,
    bool path_find,
    bool force_finish)
{
    if(force_finish || !wait_until_reached)
    {
        wait_until_reached = force_finish;
        start_pos = get_my_entity()->get_abs_position();
        last_pos = start_pos;
        target_pos = pos;
        tgtrange = radius;

        if((start_pos - target_pos).length2() <= (tgtrange*tgtrange))
        {
            if(jockey)
                stop_jockey();

            if(in_service)
                going_out_of_service();

            running_speed = fast;
        }
        else
        {
            if(jockey)
                stop_jockey();

            if(in_service && running_speed != fast)
                going_out_of_service();

            running_speed = fast;

            facing = false;

            if(!in_service)
                going_into_service();
        }

        return(true);
    }
    else
        return(false);
}
